-- 91 Procedural Isles: everything here is noise (Noise.*, the engine's,
-- the same numbers in every runtime). R draws a new archipelago: cellular
-- noise puts one island in each of its cells, simplex fbm breaks up the
-- coasts, and the autotiled map draws sand, grass and rock from the height.
-- Clouds drift on the wind and grow and melt where 3D Perlin noise (time as
-- z) says; streaks of wind follow a Perlin flow field. Space is a gale.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/91-procedural-isles.scene"
local COLS, ROWS = 28, 16
local CLOUDS, STREAKS = 14, 40
local HALF_W, HALF_H = 700, 420

local captions = true
local map
local seed = 91
local t = 0
local gale = false
local wind = 1          -- eases between 1 and the gale's 2.6
local clouds, gusts = {}, {}
local rng = 7

local function rand()
    rng = (rng * 1103515245 + 12345) % 2147483648
    return rng / 2147483648
end

local function build()
    -- Roughness for the coasts: one call for the whole map.
    local rough = Noise.grid(0, 0, COLS, ROWS, 1, { kind = "simplex", octaves = 4, frequency = 0.13, seed = seed })
    for r = 0, ROWS - 1 do
        for c = 0, COLS - 1 do
            -- One island per cell of the cellular noise; f1 is how far this
            -- tile is from that island's heart.
            local f1 = Noise.cellular(c * 0.14 + 0.3, r * 0.14 + 0.7, seed)
            local h = 0.58 - f1 * 1.35 + rough[r * COLS + c + 1] * 0.3
            -- The map's own edge is open sea.
            local edge = math.min(c, COLS - 1 - c, r, ROWS - 1 - r)
            if edge < 2 then h = h - (2 - edge) * 0.22 end
            local terrain = 0
            if h > 0.42 then terrain = 3 elseif h > 0.25 then terrain = 2 elseif h > 0.14 then terrain = 1 end
            Tilemap.set_tile(map, "ground", c, r, terrain)
        end
    end
end

local function place_gust(g, anywhere)
    if anywhere then
        g.x = (rand() * 2 - 1) * HALF_W
    else
        g.x = -HALF_W
    end
    g.y = (rand() * 2 - 1) * HALF_H
    g.speed = 0.8 + rand() * 0.5
    Transform.set_position(g.e, g.x, g.y)
    Trail.clear(g.e)
end

function init(entity)
    map = Entity.find_by_name("Map")
    for i = 0, CLOUDS - 1 do
        clouds[#clouds + 1] = {
            e = Entity.find_by_name("Cloud" .. i),
            shadow = Entity.find_by_name("Shadow" .. i),
            x = (rand() * 2 - 1) * HALF_W,
            y = (rand() * 2 - 1) * (HALF_H - 80),
            scale = 0.7 + rand() * 0.7,
            k = i,
        }
    end
    for i = 0, STREAKS - 1 do
        local g = { e = Entity.find_by_name("Gust" .. i) }
        place_gust(g, true)
        gusts[#gusts + 1] = g
    end
    build()
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("R") then
        seed = seed + 1
        build()
    end
    if Input.is_key_just_pressed("Space") then gale = not gale end
    wind = wind + ((gale and 2.6 or 1) - wind) * math.min(1, dt * 1.5)
    t = t + dt

    -- Clouds ride the prevailing wind; how much of each there is comes from
    -- noise in space and time, so they thicken and thin as they go.
    for _, cl in ipairs(clouds) do
        cl.x = cl.x + 22 * wind * dt * (0.8 + cl.scale * 0.3)
        cl.y = cl.y + 5 * wind * dt
        if cl.x > HALF_W + 200 then cl.x = -HALF_W - 200 end
        if cl.y > HALF_H then cl.y = -HALF_H end
        local d = Noise.fractal(cl.x * 0.0022, cl.y * 0.0022,
            { kind = "perlin3", octaves = 3, z = t * 0.07 + cl.k * 0.37, seed = 17 })
        local a = math.max(0, math.min(1, (d + 0.12) * 2.6))
        local s = cl.scale * (0.75 + 0.35 * a)
        Transform.set_position(cl.e, cl.x, cl.y)
        Transform.set_scale(cl.e, s, s)
        Sprite.set_color(cl.e, 1, 1, 1, 0.88 * a)
        -- The shadow falls away from a sun in the north-west.
        Transform.set_position(cl.shadow, cl.x + 46, cl.y - 70)
        Transform.set_scale(cl.shadow, s, s * 0.9)
        Sprite.set_color(cl.shadow, 0, 0.03, 0.08, 0.28 * a)
    end

    -- Streaks follow the flow field: the wind's direction bends with Perlin
    -- noise over the map, and drifts with time.
    for _, g in ipairs(gusts) do
        local a = 0.18 + Noise.perlin(g.x * 0.0028, g.y * 0.0028 + t * 0.12, seed) * 1.1
        local v = 150 * wind * g.speed * (0.8 + 0.4 * Noise.perlin3(g.x * 0.004, g.y * 0.004, t * 0.3, 5))
        g.x = g.x + math.cos(a) * v * dt
        g.y = g.y + math.sin(a) * v * dt
        if g.x > HALF_W or g.y > HALF_H or g.y < -HALF_H then
            place_gust(g, false)
        else
            Transform.set_position(g.e, g.x, g.y)
        end
    end
end
